import { isSignatureProjectGoal, isCanvassingProjectGoal } from '~/utils/typeCheckers/projectItem';
import type { SignatureProjectGoal, CanvassingProjectGoal } from '~/client';

export function goal(value: string | SignatureProjectGoal | CanvassingProjectGoal, label?: string) {
  let processedValue: string = '';
  if (typeof value === 'string') {
    processedValue = processValue(value);
    return `${processedValue} ${label}`;
  } else if (isSignatureProjectGoal(value)) {
    processedValue = processValue(value.signatures_goal.toString());
    return `${processedValue} Signatures`;
  } else if (isCanvassingProjectGoal(value)) {
    processedValue = processValue(value.total_voters.toString());
    return `${processedValue} Voters`;
  }
}

function processValue(value: string) {
  return value.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}
